WITH with_dims AS (SELECT s.*, p2.store_name, p2.opened_date, p2.region FROM inventory s INNER JOIN stores p2 ON s.store_id = p2.id WHERE p2.city IN ('Berlin', 'Singapore')), with_windows AS (SELECT id, store_id, last_restock, store_name, opened_date, AVG(quantity) OVER (PARTITION BY region, product_id ORDER BY quantity, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS quantity_avg_2_prior, LAG(quantity, 2) OVER (PARTITION BY YEAR(opened_date), product_id ORDER BY last_restock, id) AS prev_quantity, SUM(quantity) OVER (PARTITION BY product_id) AS product_id_sum_quantity, ROW_NUMBER() OVER (ORDER BY last_restock DESC, id) AS seq_no, LEAD(quantity, 1) OVER (PARTITION BY region ORDER BY opened_date, id) AS next_quantity FROM with_dims), valid AS (SELECT *, CAST(seq_no AS DOUBLE) AS seq_no_num FROM with_windows WHERE last_restock > TO_DATE('2023-07-10')), with_dims_inventory AS (SELECT s.id, s.store_id, s.last_restock, s.store_name, s.opened_date, s.prev_quantity, s.product_id_sum_quantity, s.seq_no, s.next_quantity, s.seq_no_num, d.store_name AS store_store_name, d.city FROM valid s LEFT JOIN stores d ON s.store_id = d.id), with_windows_inventory AS (SELECT *, AVG(prev_quantity) OVER (PARTITION BY city ORDER BY opened_date, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS prev_quantity_avg_2_prior, NTILE(10) OVER (PARTITION BY city ORDER BY seq_no DESC, id) AS seq_no_bucket, MAX(product_id_sum_quantity) OVER (PARTITION BY store_id, city) AS store_id_max_product_id_sum_quantity, AVG(next_quantity) OVER (PARTITION BY store_id, city ORDER BY seq_no_num, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS next_quantity_avg_3 FROM with_dims_inventory), stats AS (SELECT CASE WHEN next_quantity_avg_3 >= 211 THEN 'PREMIUM' ELSE 'STANDARD' END AS next_quantity_avg_3_tier, CASE WHEN seq_no >= 8 THEN 'HIGH' ELSE 'LOW' END AS seq_no_tier, PERCENTILE_APPROX(seq_no, ARRAY(0.25, 0.5, 0.75)) AS seq_no_quartiles, COUNT(*) AS event_count, PERCENTILE_APPROX(prev_quantity_avg_2_prior, 0.9) AS prev_quantity_avg_2_prior_p90, COUNT(CASE WHEN city = 'Bangkok' THEN 1 END) AS bangkok_count, MAX(product_id_sum_quantity) FILTER (WHERE city = 'London') AS london_max_product_id_sum_quantity FROM with_windows_inventory GROUP BY CASE WHEN next_quantity_avg_3 >= 211 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN seq_no >= 8 THEN 'HIGH' ELSE 'LOW' END) SELECT next_quantity_avg_3_tier, seq_no_tier, bangkok_count, london_max_product_id_sum_quantity FROM stats ORDER BY next_quantity_avg_3_tier
